// Автогенерируется из download/trademarks.json
// Не редактируйте вручную — используйте scripts/convert_trademarks.py

export interface Trademark {
  id: number;
  name: string;
  description: string;
  registrationNumber: string;
  classes: number[];
  price: number | null;
  priceType: 'fixed' | 'contract';
  seller: string;
  sellerEmail: string;
  sellerPhone: string;
  type: 'verbal' | 'combined';
  tariff: 'premium' | 'profi' | 'start';
  isPremium: boolean;
  // NEW-знаки (свежедобавленные из onlineznak.ru 2026-07-30) — оранжевый бейдж «NEW»
  isNew?: boolean;
  imageUrl: string;
  fipsUrl: string;
  views: number;
  // Опционально: особое отображение в плейсхолдере (крупный заголовок + мелкий подзаголовок)
  displayTitle?: string;
  displaySubtitle?: string;
  // Локализованные субтитры (ЗАКОН-3 — Правило 4 про descriptions)
  // displayTitle обычно одинаковый на всех языках (бренд-нейм), subtitle надо переводить
  displaySubtitleEn?: string;
  displaySubtitleZh?: string;
}

